import {matchesSearch} from './search.js';
import {ARCHIVE_START,availableDay,puzzleOnDay,latestDayForCase,monthCells,shiftMonth,nextArchiveDay,dateForDay} from './calendar.js';
import {investigationQuestions} from './guidance.js';
import {characters,posts,stories,puzzles,postById,personById,traces,puzzleById} from './data.js';
import {STORAGE_KEY,loadState,saveState,progressFor,freshProgress,checkAnswer,dailyPuzzle,remainingRoutes,protectionIds,recordDailyCompletion,dailyCompleted} from './engine.js';
import {lessons,assessments,recordAttempt,recordOutcome,recordDecision,learningSummary,assessmentScore} from './learning.js';
import {dailyLocked,dayKey} from './engine.js';
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
let state=loadState(localStorage),feedback='',toastTimer,query='',filter='Todos',slide=0,storyPage=0,storyId=null,modalKind=null,postId=null;
let storyTimer=null,storyElapsed=0,storyLastTick=0,storyPaused=false,storyHolding=false,storyFeed=false;
const STORY_DURATION=8000;
const params=new URLSearchParams(location.search);
let currentDay=availableDay(params.get('day'))?params.get('day'):(puzzleById[params.get('case')]?latestDayForCase(params.get('case')):null)||dayKey();
let currentId=availableDay(params.get('day'))?puzzleOnDay(currentDay).id:puzzleById[params.get('case')]?params.get('case'):dailyPuzzle().id;
let calendarMonth=currentDay.slice(0,7),celebration=null;
const caseQuery=()=>`case=${currentId}&day=${currentDay}`;
const formatDay=(day,options={day:'numeric',month:'long',year:'numeric'})=>new Intl.DateTimeFormat('pt-BR',{...options,timeZone:'America/Sao_Paulo'}).format(dateForDay(day));
const current=()=>puzzleById[currentId],progress=()=>{const p=progressFor(state,currentId);if(dailyLocked(state,currentId))p.status='solved';return p;};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pixelArrow='<svg class="pixel-arrow" viewBox="0 0 16 16" aria-hidden="true"><path fill="currentColor" d="M6 2h8v8h-2V6l-8 8-2-2 8-8H6z"/></svg>';
const sym=(s)=>`<span class="icon" aria-hidden="true">${s}</span>`;
function toast(text){document.querySelector('#toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.querySelector('#toast').textContent='',2800);}
function mutate(fn){state=loadState(localStorage);fn(state);if(!saveState(localStorage,state))toast('Não foi possível salvar neste navegador.');}
function change(fn){mutate(s=>fn(progressFor(s,currentId)));}
function avatar(id,cls=''){const c=personById[id];return `<img class="avatar ${cls}" src="${esc(c.avatar)}" alt="Avatar de ${esc(c.name)}" width="192" height="192" loading="lazy" decoding="async">`;}
function scene(art){return `<img class="scene unique-scene" src="${esc(art.src)}" width="384" height="384" loading="lazy" decoding="async" alt="" draggable="false">`;}
const isNetwork=()=>location.hash.startsWith('#network');
const isProtected=()=>isNetwork()&&new URLSearchParams(location.search).get('mode')==='protect';
function networkUrl(post=null,protect=false){return `/?${caseQuery()}${protect?'&mode=protect':''}#network${post?'/post/'+post:''}`;}
function networkLink(text,post=null,cls='secondary',protect=false){return `<a class="${cls}" href="${networkUrl(post,protect)}">${esc(text)}${cls==='network-button'?'':pixelArrow}</a>`;}
function badge(level){return `<span class="difficulty ${level==='Fácil'?'easy':level==='Médio'?'medium':'hard'}"><i></i>${level}</span>`;}
function setCase(id,day=null){if(!puzzleById[id])return;currentId=id;currentDay=day&&availableDay(day)&&puzzleOnDay(day).id===id?day:latestDayForCase(id)||dayKey();calendarMonth=currentDay.slice(0,7);feedback='';celebration=null;mutate(s=>s.lastPuzzle=id);history.replaceState(null,'',`/?${caseQuery()}#play`);closeModal();render();window.scrollTo({top:0,behavior:'instant'});}
function selectDay(day){if(availableDay(day))setCase(puzzleOnDay(day).id,day);}
function copyright(){return `<span class="copyright">© ${new Date().getFullYear()} EXPOSED! Todos os direitos reservados.</span><button class="text-button credits-link" data-act="credits">Créditos</button><button class="text-button" data-act="learning">Meu percurso</button><a class="text-button" href="/privacidade.html">Política de Privacidade</a>`;}
function header(){return `<header class="topbar"><a class="brand" href="/" aria-label="EXPOSED! Enigma do dia">EXPOSED<span>!</span></a><div class="top-actions"><button class="quiet" data-act="library">${sym('▦')}<span>Calendário</span></button><button class="quiet help" data-act="help" aria-label="Como jogar">?</button></div></header>`;}
function render(){document.title=isNetwork()?'Órbita — a rede do EXPOSED!':'EXPOSED! — '+current().title;root.innerHTML=isNetwork()?network():game();bindInputs();}
function game(){const p=current(),s=progress(),daily=currentDay===dayKey();return `${header()}<main class="game"><div class="game-topline"><button class="daily-label ${daily?'current':''}" data-act="daily">✦ ${daily?(dailyCompleted(state)?'ENIGMA DO DIA CONCLUÍDO':'ENIGMA DO DIA'):'VOLTAR AO ENIGMA DO DIA'}</button><span class="game-date">${formatDay(currentDay,{day:'numeric',month:'short',year:'numeric'})}</span></div><section class="riddle-area" aria-labelledby="riddle"><div class="puzzle-meta">${badge(p.level)}<span class="puzzle-kind">${p.level==='Fácil'?'Observação':p.level==='Médio'?'Conexão':'Interpretação'}</span><span class="puzzle-title">${esc(p.title)}</span></div><h1 id="riddle">${esc(p.phrase)}</h1>${s.status==='open'?`<p class="investigation-question">${esc(investigationQuestions[p.id])}</p>${tutorial()}`:''}${s.status==='open'?`<div class="network-cta">${networkLink('Explorar a rede',null,'network-button')}<span>Abra os posts e guarde os detalhes que podem explicar a frase.</span><a class="text-button" href="${networkUrl()}" target="exposed-network">Prefiro explorar em outra aba ↗</a></div>`:''}${s.status==='open'?answerArea():revealArea()}<div class="game-utilities"><button class="utility" data-act="hints">${sym('✧')} Dicas <small>${s.hints}/3</small></button><button class="utility" data-act="notebook">${sym('▤')} Caderno <small>${s.saved.length}</small></button>${dailyLocked(state,currentId)?'<span class="small muted">Resultado diário registrado</span>':`<button class="utility muted" data-act="${s.status==='open'?'reveal-confirm':'replay-confirm'}">${s.status==='open'?'Revelar solução':'Refazer enigma'}</button>`}</div></section><footer class="game-footer">${copyright()}</footer></main>`;}
function answerArea(){const s=progress();return `<section class="response-workspace" aria-label="Sua resposta e pistas"><form id="answer-form" class="answer-form"><label class="answer-label" for="answer">O que você descobriu?</label><div class="answer-row"><input id="answer" value="${esc(s.answer)}" placeholder="Sua resposta em poucas palavras" autocomplete="off" spellcheck="false" maxlength="150" aria-describedby="answer-help"><button class="primary" type="submit">Conferir</button></div><div id="answer-help" class="answer-help">A resposta precisa combinar com as pistas que você guardou.</div></form><div class="evidence-summary"><button class="text-button" data-act="notebook">${s.selected.length?`✓ ${s.selected.length} pista${s.selected.length===1?'':'s'} junto da resposta · Ver no caderno`:'Ainda sem pistas · Abrir caderno'} →</button>${s.selected.length?`<p class="attached-preview">${s.selected.slice(0,2).map(id=>esc(traces[id].text)).join(' · ')}${s.selected.length>2?' · …':''}</p>`:''}</div><p class="answer-feedback ${feedback.startsWith('Boa')?'warm':''}" role="status">${esc(feedback)}</p></section>`;}
function lesson(type){return `<div class="micro-lesson"><span class="pixel-mini">${type==='rastro'?'RASTRO':type==='conexao'?'CONEXÃO':'SUPOSIÇÃO'}</span><p>${type==='rastro'?'Abra um post na rede e guarde um detalhe no caderno. Esse detalhe observável é um rastro.':type==='conexao'?'Uma pista sozinha pode não bastar. Guarde os dois rastros e selecione ambos no caderno.':'Parece verdade ou dá para provar? Compare as datas antes de concluir.'}</p></div>`;}
function revealArea(){const p=current(),s=progress(),solved=s.status==='solved',fresh=celebration;celebration=null;return `<section class="revelation ${solved?'is-solved':'is-revealed'}"><div class="completion-banner ${solved?'solved-banner':'revealed-banner'} ${fresh==='solve'?'just-completed':''}" role="status"><span class="completion-mark" aria-hidden="true">${solved?'✓':'◇'}</span><div><span class="result-label">${solved?'CONEXÃO ENCONTRADA':'SOLUÇÃO REVELADA'}</span><h2 class="completion-title">${solved?'Boa! Você conectou as pistas.':'Veja como as pistas se encaixam.'}</h2><p>${solved?'Sua resposta e suas evidências fazem sentido juntas.':'Descobrir o caminho também faz parte do jogo.'}</p></div></div><div class="discovery-body"><span class="discovery-label">${solved?'SUA DESCOBERTA':'A RESPOSTA'}</span><h3 class="discovery-answer">${esc(p.answer)}</h3><p>${esc(p.explanation)}</p>${educationalReveal()}<div class="source-links">${[...new Set(p.routes.flat().map(id=>traces[id].post))].map(id=>networkLink(postById[id].title,id,'source-link')).join('')}</div><div class="protection-invitation"><button class="primary" data-act="protection">◇ ${s.protectionDone?'Rever proteção':'Agora, proteja os rastros'}</button>${s.protectionDone?`<div class="protected-label ${fresh==='protect'?'just-protected':''}" role="status"><strong>✓ Rastros protegidos!</strong><span>Você concluiu a proteção deste caso.</span></div>`:''}</div></div><nav class="next-actions" aria-label="Depois da investigação"><button class="next-action next-primary" data-act="next"><span>Próximo enigma</span><b aria-hidden="true">→</b></button><button class="next-action next-calendar" data-act="library"><span>Escolher um dia</span><b aria-hidden="true">▦</b></button>${networkLink('Voltar à rede',null,'next-action next-network')}</nav></section>`;}
function openModal(html,kind){
 const same=modal.open&&modalKind===kind,active=modal.contains(document.activeElement)?document.activeElement:null;
 const field=active?.dataset.evidence?'evidence':active?.dataset.protect?'protect':null,value=field?active.dataset[field]:null,scroll=modal.scrollTop;
 stopStoryTimer();modalKind=kind;modal.innerHTML=html;if(!modal.open)modal.showModal();
 const target=field?Array.from(modal.querySelectorAll(`[data-${field}]`)).find(el=>el.dataset[field]===value):null;
 (target||(!same?modal.querySelector('button,input'):null))?.focus({preventScroll:true});
 if(same)modal.scrollTop=scroll;
}
function closeModal(){stopStoryTimer();modal.close();modalKind=null;postId=null;storyId=null;}
function mh(title,kicker=''){return `<div class="modal-header"><div>${kicker?`<span class="eyebrow">${kicker}</span>`:''}<h2>${title}</h2></div><button class="icon-button" data-act="close" aria-label="Fechar">×</button></div>`;}
function calendar(){const today=dayKey(),monthLabel=formatDay(calendarMonth+'-01',{month:'long',year:'numeric'}),cells=monthCells(calendarMonth,today),names=['Todos','Fácil','Médio','Difícil'];return `<section class="mini-calendar" aria-label="Calendário de enigmas"><div class="calendar-heading"><button class="calendar-nav" data-act="month-prev" aria-label="Mês anterior" ${calendarMonth<=ARCHIVE_START.slice(0,7)?'disabled':''}>‹</button><h3>${esc(monthLabel)}</h3><button class="calendar-nav" data-act="month-next" aria-label="Próximo mês" ${calendarMonth>=today.slice(0,7)?'disabled':''}>›</button></div><div class="calendar-tabs" aria-label="Filtrar dificuldade">${names.map(v=>`<button data-act="filter" data-id="${v}" aria-pressed="${filter===v}" class="${filter===v?'active':''}">${v}</button>`).join('')}</div><div class="calendar-weekdays" aria-hidden="true">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(v=>`<span>${v}</span>`).join('')}</div><div class="calendar-grid">${cells.map(cell=>{if(!cell)return '<span class="calendar-gap" aria-hidden="true"></span>';const {day,number,puzzle:p,available}=cell;if(!available)return `<button class="calendar-day unavailable" disabled aria-label="${formatDay(day)} — ${day>today?'Ainda não disponível':'Antes do início do arquivo'}"><span>${number}</span></button>`;const match=filter==='Todos'||p.level===filter,solved=state.progress[p.id]?.status==='solved',recorded=state.dailyCompletions[day]===p.id,revealed=state.progress[p.id]?.status==='revealed',isToday=day===today;return `<button class="calendar-day ${p.level==='Fácil'?'level-easy':p.level==='Médio'?'level-medium':'level-hard'} ${day===currentDay?'current':''} ${isToday?'today':''} ${solved?'solved':''} ${match?'':'filtered'}" data-act="choose-day" data-id="${day}" ${match?'':'disabled'} title="${formatDay(day)} · ${esc(p.title)} · ${p.level}" aria-label="${formatDay(day)}, ${esc(p.title)}, ${p.level}${isToday?', hoje':''}${recorded?', concluído neste dia':solved?', caso já resolvido':revealed?', solução já vista':''}${match?'':', fora do filtro'}" ${day===currentDay?'aria-current="date"':''}><span>${number}</span><small>${isToday?'Hoje':solved?'✓':revealed?'Visto':''}</small></button>`;}).join('')}</div><div class="calendar-legend"><span class="legend-easy">Fácil</span><span class="legend-medium">Médio</span><span class="legend-hard">Difícil</span><span>✓ Caso resolvido</span></div><p class="calendar-note"><strong>Escolha um dia.</strong> Jogue no seu ritmo.</p><p class="calendar-context">15 enigmas em rodízio. Seu progresso acompanha cada caso, mesmo quando ele reaparece.</p><button class="text-button calendar-today" data-act="calendar-today">Ir para o mês de hoje →</button></section>`;}
function library(){openModal(`${mh('Escolha um dia para investigar','SEU CALENDÁRIO')}<div class="calendar-modal">${calendar()}</div>`,'library');}
function hints(){const p=current(),s=progress();openModal(`${mh('Uma pista de cada vez','SEM PRESSA, SEM PENALIDADE')}<div class="modal-body hints"><p>${esc(p.phrase)}</p>${p.hints.map((h,i)=>`<div class="hint-row ${i<s.hints?'unlocked':''}"><span class="hint-number">${i+1}</span><p>${i<s.hints?esc(h):['Onde procurar','O que conectar','Mais perto da resposta'][i]}</p></div>`).join('')}${s.hints<3?'<button class="primary" data-act="hint-next">Abrir próxima dica</button>':'<p class="muted">Ainda travou? Pode revelar a solução e seguir jogando.</p>'}<button class="text-button" data-act="reveal-confirm">Revelar solução</button></div>`,'hints');}
function notebook(){const s=progress();openModal(`${mh('Seu caderno',esc(current().title))}<div class="modal-body"><p class="notebook-question">${esc(investigationQuestions[currentId])}</p><p class="muted">Estas são suas pistas. Deixe marcadas as que ajudam a responder à pergunta.</p>${s.saved.length?`<div class="notebook-list">${s.saved.map(id=>{const t=traces[id],p=postById[t.post];return `<div class="notebook-item ${s.selected.includes(id)?'included':''}"><label><input type="checkbox" data-evidence="${id}" ${s.selected.includes(id)?'checked':''}><span><span class="trace-type">${t.type==='photo'?'Detalhe visual':'Comentário'} · @${personById[p.who].handle}</span><strong>${esc(t.text)}</strong><small class="evidence-state">${s.selected.includes(id)?'Vai junto da resposta':'Só guardado no caderno'}</small></span></label><div class="notebook-bottom">${networkLink(p.title,p.id,'text-button')}<button class="text-button muted" data-act="unsave" data-id="${id}">Remover</button></div></div>`;}).join('')}</div><div class="notebook-next"><p role="status">${s.selected.length?`${s.selected.length} rastro${s.selected.length===1?'':'s'} acompanha${s.selected.length===1?'':'m'} sua conclusão. Você pode mudar essa escolha quando quiser.`:'Nenhum rastro marcado. Selecione uma pista ou continue explorando.'}</p><button class="primary" data-act="answer-return">${s.status!=='open'?'Voltar à descoberta':s.selected.length?'Responder com estas pistas →':'Voltar ao enigma'}</button><button class="text-button" data-act="explore-return">Continuar procurando</button></div>`:`<div class="empty-state"><h3>Vamos encontrar uma pista?</h3><p>Abra um post na rede e toque em “Guardar rastro” no detalhe que chamou sua atenção.</p><button class="primary" data-act="explore-return">Explorar a rede →</button><button class="text-button" data-act="start-hint">Por onde começo?</button></div>`}</div>`,'notebook');}
function help(){openModal(`${mh('É só investigar e responder','COMO JOGAR')}<div class="modal-body help-body"><ol><li><strong>Leia o mistério.</strong> A pergunta abaixo dele diz o que você quer descobrir.</li><li><strong>Procure na rede.</strong> Abra os posts. Se uma informação ajudar, toque em “Guardar rastro”.</li><li><strong>Volte e responda.</strong> Escreva o que descobriu. As pistas guardadas vão junto para comprovar sua resposta.</li></ol><p>Travou? Use “Por onde começo?” ou as dicas. Não perde pontos.</p><p class="small muted">“Salvar publicação” é só um favorito. Para levar uma pista à resposta, use “Guardar rastro”.</p><button class="primary" data-act="guide-enable">Entendi, vamos jogar</button></div>`,'help');}

function confirmAction(replay=false){openModal(`${mh(replay?'Refazer este enigma?':'Ver como os rastros se conectam?')}<div class="modal-body"><p>${replay?'As pistas, dicas e alterações deste desafio serão reiniciadas. Os outros continuam guardados.':'Você verá a resposta e a explicação. O desafio ficará marcado como “Solução vista” e poderá ser refeito.'}</p><div class="button-row"><button class="secondary" data-act="close">Continuar jogando</button><button class="primary" data-act="${replay?'replay':'reveal'}">${replay?'Refazer':'Ver solução'}</button></div></div>`,'confirm');}
function protection(){const p=current(),s=progress(),remaining=remainingRoutes(p,s.protected);openModal(`${mh(p.contextProtection?'O contexto também protege':'Mude o que fica visível','LABORATÓRIO DE PRIVACIDADE')}<div class="modal-body"><p>${esc(p.protection)}</p><p class="small muted">Uma simulação deste desafio. As alterações aparecem na aba da rede em “Simulação protegida”. O arquivo original continua disponível para investigar.</p><div class="protection-list">${protectionIds(p).map(id=>{const t=traces[id],on=s.protected.includes(id);return `<div class="protection-item"><label class="protection-control"><input type="checkbox" data-protect="${id}" ${on?'checked':''}><span><strong>${esc(t.action)}</strong><span>${esc(postById[t.post].title)}</span></span></label><blockquote class="${on?'redacted':''}">${esc(on?t.protectedText:t.text)}</blockquote>${networkLink('Ver no perfil',t.post,'text-button',true)}</div>`;}).join('')}</div><div class="protection-result ${remaining.length?'pending':'done'}" role="status"><strong>${remaining.length?(p.contextProtection?'A publicação ainda permite a confusão.':'Ainda há rastros conectados.'):(p.contextProtection?'Agora a data acompanha a imagem.':'A conexão foi interrompida.')}</strong><p>${remaining.length?(p.contextProtection?'A data de postagem ainda pode ser confundida com a data da foto.':`Ainda é possível reconstruir a informação por ${remaining.length} caminho${remaining.length===1?'':'s'}.`):(p.contextProtection?'A imagem deixa claro que é uma lembrança.':'Com os rastros que restaram neste caso, já não dá para sustentar a descoberta.')}</p>${remaining.length?`<ul>${remaining.map(route=>`<li>${route.map(id=>esc(postById[traces[id].post].title)+' — '+esc(traces[id].label||'comentário')).join(' + ')}</li>`).join('')}</ul>`:''}</div>${protectionLesson()}<div class="button-row"><button class="primary" data-act="finish" ${remaining.length?'disabled':''}>Concluir proteção ✓</button><button class="text-button" data-act="reset-protection">Restaurar rastros</button></div></div>`,'protection');}
function saveTrace(id){const has=progress().saved.includes(id);change(s=>{s.saved=has?s.saved.filter(x=>x!==id):[...s.saved,id];s.selected=has?s.selected.filter(x=>x!==id):[...s.selected,id];});toast(has?'Rastro retirado.':'Rastro incluído na sua resposta. Veja no caderno.');if(postId)openPost(postId,false);else render();}
function network(){const route=location.hash.split('/'),profile=route[1]==='profile'?personById[route[2]]:null,saved=route[1]==='saved',search=route[1]==='search';const shown=posts.filter(p=>(!profile||p.who===profile.id)&&(!saved||state.bookmarks.includes(p.id))&&(!search||matchesSearch(`${p.title} ${p.caption} ${personById[p.who].name} ${personById[p.who].handle} ${p.parts.map(t=>isProtected()&&progress().protected.includes(t.id)?t.protectedText:t.text).join(' ')}`,query)));return `<div class="social-app"><aside class="social-nav"><a class="orbita-logo" href="#network">órbita<span>✳</span></a><nav><a class="${!profile&&!saved&&!search?'active':''}" href="#network">${sym('☷')}<span>Feed</span></a><a class="${search?'active':''}" href="#network/search">${sym('⌕')}<span>Buscar</span></a><button data-act="notebook">${sym('▤')}<span>Caderno <small>${progress().saved.length}</small></span></button><a class="${saved?'active':''}" href="#network/saved">${sym('▣')}<span>Posts salvos</span></a></nav><div class="social-people">${characters.map(c=>`<a href="#network/profile/${c.id}">${avatar(c.id)}<span>${c.name.split(' ')[0]}</span></a>`).join('')}</div><a class="back-to-puzzle" href="/?${caseQuery()}#play">← Voltar ao enigma</a><p class="social-disclaimer">Uma rede fictícia.<br>Uma reflexão real.</p></aside><div class="social-main"><div class="social-top"><div class="network-view-status"><span>${isProtected()?'◇ SIMULAÇÃO PROTEGIDA':'ARQUIVO ORIGINAL'}</span>${progress().protected.length?`<button class="network-compare" data-act="compare-view">${isProtected()?'Ver original':'Ver protegido'}</button>`:''}</div><a href="/?${caseQuery()}#play">Enigma ↗</a></div><div class="investigation-strip"><div><span class="eyebrow">${isProtected()?'SUAS ALTERAÇÕES NESTE DESAFIO':'VOCÊ ESTÁ INVESTIGANDO'}</span><strong>${esc(current().phrase)}</strong></div><button class="quiet" data-act="${isProtected()?'protection':'notebook'}">${isProtected()?'◇ Proteção':'▤ Caderno'}</button></div>${isProtected()?'<p class="simulation-note">Os detalhes protegidos aparecem alterados aqui. O arquivo original permanece disponível para refazer os enigmas.</p>':''}${tutorial()}${profile?profileHeader(profile):search?'':`<div class="stories-row">${stories.map((s,i)=>`<button class="story-circle" data-act="story" data-id="${i}">${avatar(s.who)}<span>${personById[s.who].name.split(' ')[0]}</span></button>`).join('')}</div>`}${search?`<div class="search-box">⌕<label class="sr-only" for="network-search">Buscar perfis e publicações</label><input id="network-search" placeholder="Buscar pessoas, posts ou palavras…" value="${esc(query)}" autocomplete="off"><button class="text-button" data-act="clear-search">Limpar</button></div><div class="search-profiles" aria-label="Perfis encontrados">${characters.filter(c=>matchesSearch(c.name+' '+c.handle+' '+c.bio,query)).map(c=>`<a href="#network/profile/${c.id}">${avatar(c.id)}<span>${c.name}<small>@${c.handle}</small></span></a>`).join('')}</div>`:''}<div class="feed-heading"><h1>${profile?'Publicações':saved?'Suas publicações salvas':search?'Resultados':'Entre um post e outro'}</h1><span>${shown.length} publicações</span></div><div class="${profile?'profile-grid':'feed-list'}">${shown.length?shown.map(p=>profile?`<button class="grid-post ${protectedArt(p)}" data-act="post" data-id="${p.id}" aria-label="Abrir ${esc(p.title)}">${scene(p.art??p.scene)}<span>${esc(p.title)}</span></button>`:feedPost(p)).join(''):`<div class="empty-state"><h3>${saved?'Nenhuma publicação salva ainda.':'Nenhum resultado.'}</h3><p>${saved?'Use o marcador de uma publicação para guardá-la.':'Tente um nome ou outra palavra.'}</p></div>`}</div><footer class="social-footer">${copyright()}</footer></div><aside class="social-right"><div class="eyebrow">GENTE DA ÓRBITA</div>${characters.map(c=>`<a class="person-row" href="#network/profile/${c.id}">${avatar(c.id)}<span><strong>${c.name}</strong><small>@${c.handle}</small></span>→</a>`).join('')}<div class="network-note"><span class="pixel-mini">UM RASTRO DE CADA VEZ.</span><p>Abra um post. Leia os comentários. Guarde o detalhe que fez você pensar.</p><button class="text-button" data-act="hints">Precisa de uma dica? →</button></div><a class="mini-brand" href="/?${caseQuery()}#play">EXPOSED!</a></aside></div>`;}
function profileHeader(c){return `<div class="profile-cover" style="--profile-color:${c.color}"><span>${esc(c.tagline)}</span><span class="profile-cover-mark" aria-hidden="true">✦</span></div><section class="profile-header" style="--profile-color:${c.color}">${stories.some(s=>s.who===c.id)?`<button class="profile-story-avatar" data-act="story" data-id="${stories.findIndex(s=>s.who===c.id)}" aria-label="Ver stories de ${esc(c.name)}">${avatar(c.id,'large')}<span>Ver stories</span></button>`:avatar(c.id,'large')}<div><span class="profile-handle">@${c.handle}</span><h1>${c.name}</h1><p>${c.bio}</p><div class="profile-interests">${c.interests.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="profile-counts"><span><b>${posts.filter(p=>p.who===c.id).length}</b> publicações</span><span><b>${c.followers}</b> seguidores fictícios</span></div></div></section><div class="profile-highlights">${stories.filter(s=>s.who===c.id).map(s=>`<button class="highlight-story" data-act="story" data-id="${stories.indexOf(s)}" aria-label="Abrir destaque ${esc(s.title)} de ${esc(c.name)}">${scene(postById[s.posts[0]].art??postById[s.posts[0]].scene)}<span>${s.title}</span></button>`).join('')}<a href="#network">← Todos os perfis</a></div>`;}
function richText(text){return esc(text).replace(/@([a-z0-9_]+(?:\.[a-z0-9_]+)*)/g,(match,handle)=>{const c=characters.find(c=>c.handle===handle);return c?`<a class="mention" href="#network/profile/${c.id}" data-act="profile" data-id="${c.id}">${match}</a>`:match;});}
function protectedArt(p){return isProtected()&&p.parts.some(t=>t.type==='photo'&&progress().protected.includes(t.id))?'art-protected':'';}
const actionIcon=(kind)=>`<svg class="action-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true">${kind==='heart'?'<path d="M12 20 4 12V5h6l2 3 2-3h6v7z"/>':kind==='bookmark'?'<path d="M6 3h12v18l-6-4-6 4z"/>':'<path d="M6 3h14v18H6zM3 7h5M3 12h5M3 17h5M11 8h5M11 12h5"/>'}</svg>`;
function socialAction(p,kind){const liked=kind==='like',on=(liked?state.likes:state.bookmarks).includes(p.id);return `<button class="social-action ${liked?'like-action':'save-action'} ${on?'is-active':''}" data-act="${kind}" data-id="${p.id}" aria-pressed="${on}" aria-label="${liked?(on?'Descurtir':'Curtir'):(on?'Remover publicação salva':'Salvar publicação')} ${esc(p.title)}">${actionIcon(liked?'heart':'bookmark')}<span>${liked?(on?'Curtiu':'Curtir'):(on?'Publicação salva':'Salvar publicação')}</span>${liked?`<strong class="like-count">${p.likes+(on?1:0)}</strong>`:''}</button>`;}
function feedPost(p){const c=personById[p.who],liked=state.likes.includes(p.id),saved=state.bookmarks.includes(p.id);return `<article class="feed-post"><div class="post-header"><a href="#network/profile/${c.id}">${avatar(c.id)}<span><strong>${c.handle}</strong><small>${p.date}</small></span></a><button class="icon-button" data-act="post" data-id="${p.id}" aria-label="Abrir ${esc(p.title)}">↗</button></div><button class="feed-image ${protectedArt(p)}" data-act="post" data-id="${p.id}" aria-label="Abrir ${esc(p.title)}">${scene(p.art??p.scene)}<span class="image-title">${esc(p.title)}</span>${isProtected()&&p.parts.some(t=>progress().protected.includes(t.id))?'<span class="edited-flag">◇ Post revisado</span>':''}</button><div class="post-actions">${socialAction(p,'like')}${socialAction(p,'bookmark')}</div><div class="post-copy"><span class="likes">${p.likes+(liked?1:0)} curtidas</span><p><a href="#network/profile/${c.id}"><strong>${c.handle}</strong></a> ${richText(p.caption)}</p><button class="text-button muted" data-act="post" data-id="${p.id}">Abrir publicação e comentários</button></div></article>`;}
function casualComments(p){return (p.comments||[]).map(c=>`<div class="comment casual-comment">${avatar(c.by)}<div><a href="#network/profile/${c.by}" data-act="profile" data-id="${c.by}"><strong>${esc(personById[c.by].handle)}</strong></a><p>${richText(c.text)}</p></div></div>`).join('');}
function openPost(id,reset=true){const p=postById[id];if(!p)return;if(reset)slide=0;postId=id;const c=personById[p.who],hidden=t=>isProtected()&&progress().protected.includes(t.id);openModal(`<div class="post-modal"><button class="mobile-post-close" data-act="close" aria-label="Fechar publicação">×</button><div class="post-art"><div class="post-visual ${protectedArt(p)}">${scene(p.artSlides?.[slide]??p.art??p.slides?.[slide]??p.scene)}<div class="visual-details">${p.parts.filter(t=>t.type==='photo').map(t=>`<div class="photo-detail ${hidden(t)?'redacted':''}"><small>${esc(t.label||'Detalhe da foto')}</small><strong>${esc(hidden(t)?t.protectedText:t.text)}</strong></div>`).join('')}</div>${p.slides?`<button class="carousel prev" data-act="slide-prev" aria-label="Foto anterior">‹</button><button class="carousel next" data-act="slide-next" aria-label="Próxima foto">›</button><span class="slide-count">${slide+1}/${p.slides.length}</span>`:''}</div></div><div class="post-detail"><div class="post-header"><a href="#network/profile/${c.id}" data-act="profile" data-id="${c.id}">${avatar(c.id)}<span><strong>${c.handle}</strong><small>${p.date}</small></span></a><button class="icon-button" data-act="close" aria-label="Fechar publicação">×</button></div><div class="post-detail-scroll"><h2>${esc(p.title)}</h2><p>${richText(p.caption)}</p>${p.parts.filter(t=>t.type==='photo').map(t=>`<div class="trace-block"><span class="trace-type">${esc(t.label||'Detalhe visual')}</span><p class="${hidden(t)?'redacted':''}">${esc(hidden(t)?t.protectedText:t.text)}</p>${traceButton(t,hidden(t))}</div>`).join('')}${progress().saved.some(id=>p.parts.some(t=>t.id===id))?`<div class="post-next-step"><span>Rastro guardado para “${esc(current().title)}”.</span><div class="post-next-actions"><button class="post-answer-button" data-act="answer-return">Voltar para responder →</button><button class="text-button" data-act="notebook">Ver caderno</button></div></div>`:''}<h3 class="comments-title">Comentários</h3>${p.parts.filter(t=>t.type==='comment').map(t=>`<div class="comment">${avatar(t.by||p.who)}<div><a href="#network/profile/${t.by||p.who}" data-act="profile" data-id="${t.by||p.who}"><strong>${personById[t.by||p.who].handle}</strong></a><p class="${hidden(t)?'redacted':''}">${esc(hidden(t)?t.protectedText:t.text)}</p>${traceButton(t,hidden(t))}</div></div>`).join('')||(p.comments?.length?'':'<p class="small muted">Por enquanto, só curtidas por aqui.</p>')}${casualComments(p)}${!p.parts.length?'<p class="everyday-note">Nem todo post guarda um mistério. Às vezes, é só um momento.</p>':''}</div><div class="post-detail-footer">${socialAction(p,'like')}${socialAction(p,'bookmark')}</div></div></div>`,'post');postId=id;}
function traceButton(t,hidden){if(isProtected())return `<span class="trace-status">${hidden?'◇ Alterado na simulação':'Visível na simulação'}</span>`;const saved=progress().saved.includes(t.id);return `<button class="trace-save ${saved?'is-saved':''}" data-act="save-trace" data-id="${t.id}" aria-pressed="${saved}">${actionIcon('notebook')}<span>${saved?'Rastro no caderno':'Guardar rastro'}</span><span class="trace-action-mark" aria-hidden="true">${saved?'✓':'+'}</span></button>`;}
function stopStoryTimer(){if(storyTimer!==null)clearInterval(storyTimer);storyTimer=null;storyHolding=false;}
function story(i,page=0){const group=stories[i];if(!group||!group.posts[page])return;const p=postById[group.posts[page]],person=personById[group.who];postId=null;storyId=i;storyPage=page;storyElapsed=0;
openModal(`<div class="story-view ${protectedArt(p)}"><div class="story-bars" aria-label="Story ${page+1} de ${group.posts.length}">${group.posts.map((_,n)=>`<span class="${n<page?'seen':n===page?'current':''}"><i></i></span>`).join('')}</div><div class="story-header"><a class="story-author" href="#network/profile/${person.id}" data-act="profile" data-id="${person.id}">${avatar(person.id)}<span><b>${esc(person.handle)}</b><small>${esc(group.title)} · ${page+1}/${group.posts.length}</small></span></a><button class="icon-button story-pause" data-act="story-pause" aria-label="${storyPaused?'Reproduzir stories':'Pausar stories'}" aria-pressed="${storyPaused}">${storyPaused?'▶':'Ⅱ'}</button><button class="icon-button" data-act="close" aria-label="Fechar stories">×</button></div>${scene(p.art)}<button class="story-prev story-tap" data-act="story-prev" aria-label="Story anterior">‹</button><button class="story-next story-tap" data-act="story-next" aria-label="Próximo story">›</button><div class="story-caption"><h2>${esc(p.title)}</h2><p>${richText(p.caption)}</p><button class="story-post-link" data-act="post" data-id="${p.id}">Ver publicação e pistas ↗</button></div><span class="story-hold-hint">Toque nas laterais para navegar · segure para pausar</span></div>`,'story');storyId=i;storyPage=page;storyLastTick=performance.now();
storyTimer=setInterval(()=>{const now=performance.now(),delta=now-storyLastTick;storyLastTick=now;if(modalKind!=='story'||!modal.open){stopStoryTimer();return;}if(storyPaused||storyHolding||document.hidden||!modal.querySelector('.story-view>.scene')?.complete)return;storyElapsed+=delta;const bar=modal.querySelector('.story-bars .current i');if(bar)bar.style.transform=`scaleX(${Math.min(1,storyElapsed/STORY_DURATION)})`;if(storyElapsed>=STORY_DURATION)moveStory(1);},80);}
function moveStory(direction){if(storyId===null||modalKind!=='story')return;const group=stories[storyId],next=storyPage+direction;if(next>=0&&next<group.posts.length){story(storyId,next);return;}if(storyFeed&&stories[storyId+direction]){const id=storyId+direction;story(id,direction>0?0:stories[id].posts.length-1);return;}if(direction>0)closeModal();else story(storyId,0);}
function toggleStoryPause(){storyPaused=!storyPaused;const button=modal.querySelector('.story-pause');if(button){button.textContent=storyPaused?'▶':'Ⅱ';button.setAttribute('aria-label',storyPaused?'Reproduzir stories':'Pausar stories');button.setAttribute('aria-pressed',String(storyPaused));}}

function updateSearchResults(){
 const template=document.createElement('template');template.innerHTML=network();
 for(const selector of ['.search-profiles','.feed-heading','.feed-list']){
  const existing=root.querySelector(selector),updated=template.content.querySelector(selector);
  if(existing&&updated)existing.replaceWith(updated);
 }
}
function bindInputs(){const form=document.querySelector('#answer-form');if(form){form.onsubmit=e=>{e.preventDefault();const answer=document.querySelector('#answer').value.trim();change(s=>s.answer=answer);if(dailyLocked(state,currentId)){render();return;}const result=answer?checkAnswer(current(),answer,progress().selected):'empty';if(answer)mutate(st=>recordAttempt(st,currentId,result,progressFor(st,currentId).hints));if(result==='correct'){mutate(s=>{progressFor(s,currentId).status='solved';if(currentDay===dayKey())recordDailyCompletion(s,currentId);});feedback='';celebration='solve';}else feedback=result==='empty'?'Escreva uma resposta antes de conferir.':result==='missing-evidence'?'Boa conclusão. Falta uma pista que comprove isso. Confira o caderno ou procure mais um detalhe na rede.':'Essa resposta ainda não fecha com os rastros. Tente outra conexão ou abra uma dica.';render();if(result==='correct')document.querySelector('.completion-banner')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(result!=='correct')document.querySelector('#answer')?.focus();};document.querySelector('#answer').oninput=e=>change(s=>s.answer=e.target.value);}const search=document.querySelector('#network-search');if(search)search.oninput=e=>{query=e.target.value;updateSearchResults();};}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;const act=el.dataset.act,id=el.dataset.id;if(el.tagName==='A'&&act==='profile')e.preventDefault();switch(act){case'compare-view':{const url=new URL(location.href);if(isProtected())url.searchParams.delete('mode');else url.searchParams.set('mode','protect');const opened=postId;history.replaceState(null,'',url);render();if(opened)openPost(opened,false);toast(isProtected()?'Você está vendo suas alterações.':'Você está vendo o conteúdo original.');}break;case'answer-return':returnToAnswer();break;case'focus-answer':focusAnswer();break;case'explore-return':closeModal();if(!isNetwork())location.href=networkUrl();break;case'start-hint':change(s=>s.hints=Math.max(s.hints,1));render();hints();break;case'guide-enable':mutate(s=>s.tutorialDismissed=false);closeModal();render();break;case'tutorial-dismiss':mutate(s=>s.tutorialDismissed=true);render();break;case'learning':learningPanel();break;case'assessment':assessmentPanel(id);break;case'assessment-submit':submitAssessment(id);break;case'credits':openModal(`${mh('Créditos')}<div class="modal-body"><p>EXPOSED! · Órbita</p><p>Publicações e enigmas fictícios criados para este jogo. Pixel art produzida com geração de imagens por IA e exportada em WebP. Marina Kimberly mantém seu nome e tem visual inspirado em Marin Kitagawa. Wakana Gojo aparece em uma interpretação de fã de My Dress-Up Darling, sem vínculo oficial com a obra.</p><p>A fonte Oxanium usa a licença SIL Open Font License. Materiais de terceiros permanecem sujeitos às respectivas licenças.</p><a class="text-button" href="/assets/fonts/Oxanium-OFL.txt" target="_blank" rel="noopener">Licença da fonte</a></div>`,'credits');break;case'close':closeModal();break;case'library':library();break;case'filter':filter=id;if(modal.open&&modalKind==='library')library();else render();break;case'choose-day':selectDay(id);break;case'month-prev':if(calendarMonth>ARCHIVE_START.slice(0,7)){calendarMonth=shiftMonth(calendarMonth,-1);library();}break;case'month-next':if(calendarMonth<dayKey().slice(0,7)){calendarMonth=shiftMonth(calendarMonth,1);library();}break;case'calendar-today':calendarMonth=dayKey().slice(0,7);filter='Todos';library();break;case'choose':setCase(id);break;case'daily':setCase(dailyPuzzle().id,dayKey());break;case'help':help();break;case'hints':hints();break;case'hint-next':change(s=>s.hints=Math.min(3,s.hints+1));render();hints();break;case'notebook':notebook();break;case'unsave':change(s=>{s.saved=s.saved.filter(x=>x!==id);s.selected=s.selected.filter(x=>x!==id);});render();notebook();break;case'reveal-confirm':confirmAction();break;case'replay-confirm':if(!dailyLocked(state,currentId))confirmAction(true);break;case'reveal':if(dailyLocked(state,currentId))break;mutate(st=>recordOutcome(st,currentId,'revealed',progressFor(st,currentId).hints));change(s=>s.status='revealed');closeModal();render();break;case'replay':if(dailyLocked(state,currentId))break;mutate(s=>s.progress[currentId]=freshProgress());feedback='';closeModal();render();break;case'next':{const day=nextArchiveDay(currentDay,state);if(day)selectDay(day);else library();}break;case'protection':protection();break;case'reset-protection':change(s=>{s.protected=[];s.protectionDone=false;});render();protection();break;case'finish':if(!remainingRoutes(current(),progress().protected).length){change(s=>s.protectionDone=true);closeModal();celebration='protect';render();document.querySelector('.protected-label')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}break;case'post':storyId=null;openPost(id);break;case'profile':closeModal();location.hash='#network/profile/'+id;break;case'save-trace':saveTrace(id);break;case'like':mutate(s=>s.likes=s.likes.includes(id)?s.likes.filter(x=>x!==id):[...s.likes,id]);render();if(postId)openPost(postId,false);break;case'bookmark':mutate(s=>s.bookmarks=s.bookmarks.includes(id)?s.bookmarks.filter(x=>x!==id):[...s.bookmarks,id]);render();if(postId)openPost(postId,false);toast(state.bookmarks.includes(id)?'Publicação salva.':'Publicação removida dos salvos.');break;case'clear-search':query='';{const input=document.querySelector('#network-search');if(input){input.value='';updateSearchResults();input.focus({preventScroll:true});}}break;case'story':storyFeed=!!el.closest('.stories-row');storyPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;story(Number(id));break;case'story-pause':toggleStoryPause();break;case'story-next':moveStory(1);break;case'story-prev':moveStory(-1);break;case'slide-next':slide=(slide+1)%postById[postId].slides.length;openPost(postId,false);break;case'slide-prev':slide=(slide+postById[postId].slides.length-1)%postById[postId].slides.length;openPost(postId,false);break;}});
document.addEventListener('change',e=>{const id=e.target.dataset.evidence,prot=e.target.dataset.protect;if(id){change(s=>s.selected=e.target.checked?[...new Set([...s.selected,id])]:s.selected.filter(x=>x!==id));render();notebook();}if(prot){const enabled=e.target.checked;change(s=>{s.protected=e.target.checked?[...new Set([...s.protected,prot])]:s.protected.filter(x=>x!==prot);s.protectionDone=false;});mutate(st=>recordDecision(st,currentId,prot,enabled,remainingRoutes(current(),progressFor(st,currentId).protected).length));render();protection();}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
modal.addEventListener('cancel',()=>{stopStoryTimer();modalKind=null;postId=null;storyId=null;});
window.addEventListener('hashchange',()=>{query='';closeModal();render();deepLink();});
window.addEventListener('storage',e=>{if(e.key!==STORAGE_KEY&&e.key!==null)return;if(e.newValue===null){state=loadState(localStorage);feedback='';query='';closeModal();render();toast('Dados locais apagados.');return;}const focus=document.activeElement?.id==='answer',cursor=document.querySelector('#answer')?.selectionStart;state=loadState(localStorage);render();if(focus){document.querySelector('#answer')?.focus();document.querySelector('#answer')?.setSelectionRange(cursor,cursor);}if(modal.open){if(modalKind==='notebook')notebook();else if(modalKind==='protection')protection();else if(postId)openPost(postId,false);}toast('Caderno e progresso atualizados.');});
function deepLink(){if(location.hash==='#network/search')document.querySelector('#network-search')?.focus({preventScroll:true});if(location.hash==='#answer')focusAnswer();const parts=location.hash.split('/');if(parts[1]==='post'&&postById[parts[2]])openPost(parts[2]);}
window.name=isNetwork()?'exposed-network':'exposed-puzzle';render();deepLink();


function tutorial(){if(state.tutorialDismissed||progress().status!=='open')return '';const s=progress();return `<aside class="investigation-tip simple-guide"><span class="guide-kicker">SEU PRÓXIMO PASSO</span><p>${!s.saved.length?(isNetwork()?'Abra um post. Achou algo que ajuda? Toque em “Guardar rastro”.':'Explore os posts → guarde pistas → volte para responder.'):!s.selected.length?'Escolha no caderno quais pistas combinam com sua resposta.':isNetwork()?'Pista guardada. Continue procurando ou volte para responder.':'Suas pistas já vão junto com a resposta.'}</p>${!s.saved.length?'<button class="text-button" data-act="start-hint">Por onde começo?</button>':isNetwork()?'<button class="text-button" data-act="answer-return">Responder →</button>':''}<button class="text-button guide-dismiss" data-act="tutorial-dismiss" aria-label="Dispensar orientação">×</button></aside>`;}
function returnToAnswer(){closeModal();if(isNetwork()){location.href=`/?${caseQuery()}#answer`;return;}render();focusAnswer();}
function focusAnswer(){const input=document.querySelector('#answer');if(input){input.scrollIntoView({block:'center',behavior:'instant'});input.focus({preventScroll:true});}else document.querySelector('.revelation')?.scrollIntoView({block:'center'});}

function educationalReveal(){const p=current(),l=lessons[p.id],s=progress();const found=[...new Set(s.selected)].filter(id=>p.routes.flat().includes(id));return `<div class="educational-note"><strong>${l.category}</strong><p>${esc(l.risk)}</p>${found.length?`<details><summary>Nas evidências que você selecionou</summary>${found.map(id=>`<blockquote>${esc(traces[id].text)} <small>— ${esc(postById[traces[id].post].title)}</small></blockquote>`).join('')}</details>`:'<p class="small muted">Você revelou a solução sem selecionar seus rastros. As fontes abaixo mostram como conferi-la.</p>'}</div>`;}
function protectionLesson(){const s=progress(),routes=remainingRoutes(current(),s.protected);return `<div class="educational-note"><strong>${s.protected.length?(routes.length?'Uma edição não muda todas as fontes':'O que sua decisão mudou'):'Antes de decidir'}</strong><p>${esc(lessons[currentId].tip)}</p><p class="small">${s.protected.length?(routes.length?'Sua escolha alterou um rastro, mas ainda existe uma fonte ou combinação indicada acima. Revise os caminhos restantes.':current().contextProtection?'O contexto foi acrescentado à imagem. A lembrança continua visível.':'Nesta simulação, os rastros restantes já não sustentam essa descoberta. As fotos e os outros momentos continuam na rede.'):'Cada mudança aparece na simulação do perfil. Não é necessário abandonar a rede para escolher melhor o que compartilhar.'}</p></div>`;}
function investigationStarted(){return Object.values(state.progress).some(p=>p.status!=='open'||p.saved.length||p.hints||p.answer)||Object.values(state.learning.cases).some(c=>c.attempts);}
function learningPanel(){const rows=learningSummary(state),a=state.learning.assessment,hasHistory=Object.values(state.progress).some(p=>p.status!=='open'),observed=rows.reduce((n,r)=>n+r.total,0);openModal(`${mh('Meu percurso','APRENDIZADO NESTE NAVEGADOR')}<div class="modal-body"><p class="muted">Contamos investigações e decisões observadas desde esta atualização. Dicas são apoio, não penalidade. Repetir um caso não aumenta estes totais.</p>${observed?rows.filter(r=>r.total).map(r=>`<section class="learning-row"><strong>${r.category}</strong><p>${r.solved} de ${r.total} casos concluídos com resposta e evidências; ${r.protected} com uma decisão que interrompeu todos os caminhos naquele momento.</p><small>${r.total<2?'Ainda há poucos casos para indicar uma tendência.':r.direct>=2?`${r.direct} casos resolvidos sem corrigir resposta ou seleção: uma facilidade observada nestes casos.`:`${r.revised} casos tiveram revisão de resposta ou evidências. Vale praticar esta categoria; isso não mede sua capacidade fora do jogo.`}</small></section>`).join(''):'<p>Seu percurso começa quando você confere uma resposta ou revela uma solução. Resultados antigos continuam salvos, mas não inventamos como você chegou a eles.</p>'}<details class="assessment-entry"><summary>Comparação educativa opcional · 3 situações</summary><p>Sem nome ou dados pessoais. Situações fictícias antes e depois da experiência; tudo fica neste navegador.</p>${a.before?`<p>Antes: ${assessmentScore('before',a.before.answers)} de 3.</p>`:investigationStarted()?'<p>A etapa inicial não foi registrada antes das investigações. Você ainda pode fazer a etapa final, sem comparação.</p>':'<button class="secondary" data-act="assessment" data-id="before">Antes de investigar</button>'}${a.after?assessmentResult():hasHistory?'<button class="secondary" data-act="assessment" data-id="after">Depois de investigar</button>':'<p>A etapa final fica disponível após concluir ou revelar uma investigação.</p>'}</details></div>`,'learning');}
function assessmentResult(){const a=state.learning.assessment,score=assessmentScore('after',a.after.answers);return `<p>Depois: ${score} de 3.${a.before?` Antes: ${assessmentScore('before',a.before.answers)} de 3. As situações são diferentes e abordam os mesmos conceitos.`:' Não há resultado inicial para comparar.'}</p><p class="small muted">Este é apenas o desempenho educativo no jogo. Ele não comprova redução de incidentes reais nem mede toda a sua aprendizagem.</p>${assessments.after.map((q,i)=>`<p class="small"><strong>${a.after.answers[i]===q.answer?'✓':'Revisar'} · ${i+1}.</strong> ${q.why}</p>`).join('')}`;}
function assessmentPanel(phase){const a=state.learning.assessment,hasHistory=Object.values(state.progress).some(p=>p.status!=='open');if(!assessments[phase]||a[phase]||phase==='before'&&investigationStarted()||phase==='after'&&!hasHistory)return;openModal(`${mh(phase==='before'?'Antes de investigar':'Depois de investigar','OPCIONAL · 3 SITUAÇÕES')}<div class="modal-body"><p>Escolha o que as situações fictícias permitem concluir. Nenhuma resposta é enviada a um servidor.</p><form id="assessment-form">${assessments[phase].map((q,i)=>`<fieldset><legend>${i+1}. ${q.text}</legend>${q.options.map((o,j)=>`<label class="assessment-option"><input type="radio" name="assessment-${i}" value="${j}" required><span>${o}</span></label>`).join('')}</fieldset>`).join('')}<button type="button" class="primary" data-act="assessment-submit" data-id="${phase}">Registrar respostas</button><p class="small muted">Você pode fechar sem registrar. Cada etapa concluída é preservada.</p></form></div>`,'assessment');}
function submitAssessment(phase){const form=document.querySelector('#assessment-form');if(!form?.reportValidity()||state.learning.assessment[phase])return;const answers=assessments[phase].map((_,i)=>Number(new FormData(form).get('assessment-'+i)));mutate(s=>{if(!s.learning.assessment[phase])s.learning.assessment[phase]={answers,date:dayKey()};});learningPanel();}
let activeDay=dayKey();function checkNewDay(){const today=dayKey();if(today===activeDay)return;activeDay=today;state=loadState(localStorage);const route=new URLSearchParams(location.search);if(!route.has('case')&&!route.has('day')){currentId=dailyPuzzle().id;currentDay=today;calendarMonth=today.slice(0,7);closeModal();}render();}document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkNewDay();});setInterval(checkNewDay,60000);

// A held touch pauses the timer without advancing on release.
let holdStarted=0,suppressStoryClick=false;
modal.addEventListener('pointerdown',e=>{if(modalKind!=='story'||!e.target.closest('.story-tap,.story-view>.scene'))return;storyHolding=true;holdStarted=performance.now();});
document.addEventListener('pointerup',()=>{if(storyHolding){suppressStoryClick=performance.now()-holdStarted>220;storyHolding=false;storyLastTick=performance.now();}});
document.addEventListener('pointercancel',()=>{storyHolding=false;storyLastTick=performance.now();});
modal.addEventListener('click',e=>{if(suppressStoryClick){suppressStoryClick=false;if(e.target.closest('.story-tap')){e.stopPropagation();e.preventDefault();}}},true);
modal.addEventListener('keydown',e=>{if(modalKind!=='story')return;if(e.key==='ArrowRight'){e.preventDefault();moveStory(1);}else if(e.key==='ArrowLeft'){e.preventDefault();moveStory(-1);}else if(e.code==='Space'&&e.target===modal){e.preventDefault();toggleStoryPause();}});

document.addEventListener('visibilitychange',()=>{storyLastTick=performance.now();});
